create table public.actualizaciones_trabajo (id uuid default gen_random_uuid() not null, trabajo_id uuid not null, usuario_id uuid not null, tipo character varying(50) not null, mensaje text, progreso integer, archivos text[], created_at timestamp with time zone default now(), primary key(id));
