create table public.empresas (id uuid default gen_random_uuid() not null, nombre text not null, cif text not null, propietario_id uuid not null, logo text, descripcion text, ubicacion text, telefono text, email text, sitio_web text, token_invitacion text, verificada boolean default false, created_at timestamp with time zone default now(), updated_at timestamp with time zone default now(), primary key(id));
