create table public.portfolio (id uuid default gen_random_uuid() not null, profesional_id uuid not null, trabajo_id uuid, titulo text not null, descripcion text, categoria text, imagenes text[], ubicacion text, duracion text, presupuesto numeric(10,2), fecha_proyecto date, visible boolean default true not null, created_at timestamp with time zone default now(), contexto_proveedor text, primary key(id));
create table public.profesionales (id uuid not null, titulo text not null, tarifa_por_hora numeric(10,2), "años_experiencia" integer, idiomas text[], certificaciones jsonb default '[]'::jsonb, habilidades jsonb default '[]'::jsonb, disponible boolean default true, rating_promedio numeric(3,2) default 0, total_trabajos integer default 0, "total_reseñas" integer default 0, created_at timestamp with time zone default now(), updated_at timestamp with time zone default now(), categorias_interes text[] default '{}'::text[] not null, provincias_cobertura text[] default '{}'::text[] not null, stripe_account_id text, stripe_onboarding_completado boolean default false not null, stripe_transferencias_habilitadas boolean default false not null, stripe_payouts_habilitados boolean default false not null, stripe_requisitos_pendientes jsonb default '[]'::jsonb not null, stripe_estado_actualizado_at timestamp with time zone, presupuesto_min_interes numeric(10,2), presupuesto_max_interes numeric(10,2), primary key(id));
create table public.profiles (id uuid not null, email text not null, nombre text not null, apellido text, foto_perfil text, foto_portada text, telefono text, ubicacion text, bio text, tipo_usuario text default 'cliente'::text, verificado boolean default false, fecha_registro timestamp with time zone default now(), ultima_conexion timestamp with time zone, created_at timestamp with time zone default now(), updated_at timestamp with time zone default now(), es_admin boolean default false, documento text, empresa_id uuid, cargo_empresa text, email_notificaciones boolean default true not null, cuenta_eliminada timestamp with time zone, mayor_edad_confirmada_at timestamp with time zone, mayor_edad_version text, primary key(id));
create table public."reseñas" (id uuid default gen_random_uuid() not null, trabajo_id uuid not null, autor_id uuid not null, profesional_id uuid not null, rating integer not null, comentario text not null, tipo_proyecto text, votos_utiles integer default 0, created_at timestamp with time zone default now(), primary key(id));
create table public.solicitudes (id uuid default gen_random_uuid() not null, cliente_id uuid not null, categoria_id uuid, titulo text not null, descripcion text not null, ubicacion text not null, presupuesto_min numeric(10,2), presupuesto_max numeric(10,2), urgencia text default 'media'::text, estado text default 'abierta'::text, archivos jsonb default '[]'::jsonb, fecha_necesaria date, total_ofertas integer default 0, created_at timestamp with time zone default now(), updated_at timestamp with time zone default now(), primary key(id));
create table public.trabajos (id uuid default gen_random_uuid() not null, solicitud_id uuid, oferta_id uuid, cliente_id uuid not null, profesional_id uuid not null, titulo text not null, descripcion text, precio_acordado numeric(10,2) not null, estado text default 'pendiente'::text, fecha_inicio date, fecha_fin date, ubicacion text, archivos jsonb default '[]'::jsonb, created_at timestamp with time zone default now(), updated_at timestamp with time zone default now(), progreso integer default 0, fecha_estimada_fin timestamp with time zone, fecha_entrega timestamp with time zone, review_cliente_id uuid, review_proveedor_id uuid, horas_estimadas integer default 0, horas_registradas integer default 0, notas_privadas_proveedor text, prioridad text default 'media'::text, cancelacion_solicitada_por uuid, cancelacion_razon text, cancelacion_estado text, estado_flujo text default 'pendiente_pago'::text not null, fecha_confirmacion timestamp with time zone, cancelacion_adjuntos_solicitante text[] default '{}'::text[] not null, cancelacion_respuesta_razon text, cancelacion_adjuntos_respuesta text[] default '{}'::text[] not null, pago_bloqueado boolean default false not null, cancelacion_aceptada_por uuid, contratacion_version smallint default 2, primary key(id));
create table public.transacciones_escrow (id uuid default gen_random_uuid() not null, trabajo_id uuid not null, cliente_id uuid not null, profesional_id uuid not null, monto numeric(10,2) not null, stripe_payment_intent_id text, estado text default 'pendiente'::text, fecha_retencion timestamp with time zone, fecha_liberacion timestamp with time zone, notas text, created_at timestamp with time zone default now(), updated_at timestamp with time zone default now(), monto_base numeric(10,2), comision_cliente numeric(10,2), comision_proveedor numeric(10,2), pago_neto_proveedor numeric(10,2), monto_reembolsado numeric(10,2), retencion_plataforma numeric(10,2), fecha_reembolso timestamp with time zone, stripe_session_id text, fecha_financiacion timestamp with time zone, resultado_abono text, stripe_transfer_group text, stripe_charge_id text, stripe_transfer_id text, stripe_refund_id text, stripe_refund_status text, monto_bruto_proveedor numeric(10,2), comision_cliente_retenida numeric(10,2), liquidacion_estado text default 'pendiente'::text not null, liquidacion_operacion_id text, liquidacion_error text, comision_proveedor_original numeric(10,2) not null, liquidacion_contexto jsonb, stripe_disputa_id text, primary key(id));
